module logic;
use model {Summary,Event};
use util {reverse};
record State {balance:I64,rejected:I64,peak:I64,locked:Bool,audit:List<I64>,history:List<I64>}
record Cursor {pending:List<Event>,state:State}
fn valid_amount(value:I64)->Bool {value>=0 && value<=1000000}
fn step(state:State,event:Event)->State {
 let next=match event {
  Credit(amount)=> if valid_amount(amount) {State {...state,balance:state.balance+amount,history:List::prepend(state.balance,state.history) }} else {State {...state,rejected:state.rejected+1}},
  Debit(amount)=> if !valid_amount(amount) || state.locked || amount>state.balance {State {...state,rejected:state.rejected+1}} else {State {...state,balance:state.balance-amount,history:List::prepend(state.balance,state.history) }},
  Lock=> State {...state,locked:true}, Unlock=> State {...state,locked:false},
  Undo=> if state.locked || List::length(state.history)==0 {State {...state,rejected:state.rejected+1}} else {State {...state,balance:List::head(state.history),history:List::tail(state.history)}}
 };
 State {...next,peak:if next.balance>state.peak {next.balance} else {state.peak},audit:List::prepend(next.balance,state.audit)}
}
fn run(events:List<Event>,initial:I64)->Summary {
 let final=fold(i in List::length(events),cursor:Cursor=Cursor {pending:events,state:State {balance:initial,rejected:0,peak:initial,locked:false,audit:List::empty<I64>(),history:List::empty<I64>()}}) {
  Cursor {pending:List::tail(cursor.pending),state:step(cursor.state,List::head(cursor.pending))}
 };
  Summary {balance:final.state.balance,rejected:final.state.rejected,peak:final.state.peak,audit:reverse(final.state.audit)}
}

